/**
 * @fileoverview Test the overriding of a removed method
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-method-override'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-removed-method-override', rule, {

    valid: [

    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '5',
                    toVersion: '7.9'
                }
            },
            code: `
                /**
                 * These tests the 'disable' method for the Ext.util.ClickRepeater class
                 * that was removed in 6.5.3
                 * 
                 * We test setting 'disable' to a FunctionExpression and a primitive value.
                 */

                // test creating an instance of a class
                Ext.create('Ext.util.ClickRepeater', me.prevElEnd, {
                    disable: function () {}
                });
                Ext.create('Ext.util.ClickRepeater', me.prevElEnd, {
                    disable: true
                });

                // test extending a class
                Ext.define('MyCustomClickRepeater', {
                    extend: 'Ext.util.ClickRepeater',
                    disable: function () {}
                });
                Ext.define('MyCustomClickRepeater', {
                    extend: 'Ext.util.ClickRepeater',
                    disable: true
                });

                // test overriding a class
                Ext.define('overrides.ClickRepeater', {
                    override: 'Ext.util.ClickRepeater',
                    disable: function () {}
                });
                Ext.define('overrides.ClickRepeater', {
                    override: 'Ext.util.ClickRepeater',
                    disable: true
                });
            `,
            errors: 6
        }
    ]
});
